const HIDDEN_RARITY_IDS = new Set([1,23,101,123,201,223,301,323,401,418,501,527,113,217,225,315,411,504,509,516,518,520,523,525]);
export function getCardRarity(id) {
  id=Number(id);
  if(HIDDEN_RARITY_IDS.has(id))return null;
  const metadata=CARD_RARITIES[CARD_RARITY_IDS[id]];
  return metadata ? {...metadata} : null;
}
